def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    for r in range(h):
        for c in range(w):
            if g[r][c]==3:
                g[r][c]=4
                for x in range(c+1,w):
                    if g[r][x]==5: break
                    g[r][x]=5
    return g
